from itertools import combinations

# Generate the blocks with multiplicity
blocks = []
for _ in range(4):
    for i in range(13):
        blocks.append(frozenset([i % 13, (i+1) % 13, (i+4) % 13]))
    for i in range(13):
        blocks.append(frozenset([i % 13, (i+2) % 13, (i+7) % 13]))

# Build incidence as list of lists
inc = [[0] * 104 for _ in range(13)]
for j, block in enumerate(blocks):
    for p in block:
        inc[p][j] = 1

flat = []
for row in inc:
    flat.extend(row)
print(len(flat))
print(sum(flat))
print(flat[:104]) # first row should sum to 24, positions where 1
